export type PromptId = keyof typeof PROMPT_FILES;

export function isPromptId(value: string | undefined): value is PromptId {
  return Boolean(value && value in PROMPT_FILES);
}

export function workflowPromptId(nodeId: string): PromptId | undefined {
  return WORKFLOW_PROMPT_IDS[nodeId as keyof typeof WORKFLOW_PROMPT_IDS];
}

export function rightsPromptIds(topicId: string): readonly PromptId[] {
  const sections = RIGHTS_PROMPT_IDS[topicId as keyof typeof RIGHTS_PROMPT_IDS];
  return sections ? [sections.overview, sections.guidance, sections.warning, sections.action] : [];
}
